"""Foundation macro - GENERATED by archres_core.design.foundation (W2.2).

Do not edit: regenerate it from the Building Spec instead. The macro only *builds*; the
harness measures what it built (volume, bounding box, solids, validity).

Job parameters: none in v0 - every dimension is baked into the design, and the design
records where each one came from.
"""

import json
import os
import pathlib

import FreeCAD as App
import Part

DESIGN = json.loads(r"""
{
 "excavation": {
  "depthMm": 1800.0,
  "originXMm": -600.0,
  "originYMm": -600.0,
  "sizeXMm": 11200.0,
  "sizeYMm": 14578.0,
  "volumeM3": 293.89248
 },
 "footings": [
  {
   "depthMm": 300.0,
   "id": "F1",
   "sizeXMm": 1200.0,
   "sizeYMm": 1200.0,
   "xMm": 500.0,
   "yMm": 6689.0
  },
  {
   "depthMm": 300.0,
   "id": "F2",
   "sizeXMm": 1200.0,
   "sizeYMm": 1200.0,
   "xMm": 3500.0,
   "yMm": 6689.0
  },
  {
   "depthMm": 300.0,
   "id": "F3",
   "sizeXMm": 1200.0,
   "sizeYMm": 1200.0,
   "xMm": 6500.0,
   "yMm": 6689.0
  },
  {
   "depthMm": 300.0,
   "id": "F4",
   "sizeXMm": 1200.0,
   "sizeYMm": 1200.0,
   "xMm": 9500.0,
   "yMm": 6689.0
  }
 ],
 "gradeBeams": [
  {
   "depthMm": 400.0,
   "from": "F1",
   "id": "GB1",
   "lengthMm": 3000.0,
   "to": "F2",
   "widthMm": 300.0,
   "xMm": 2000.0,
   "yMm": 6689.0
  },
  {
   "depthMm": 400.0,
   "from": "F2",
   "id": "GB2",
   "lengthMm": 3000.0,
   "to": "F3",
   "widthMm": 300.0,
   "xMm": 5000.0,
   "yMm": 6689.0
  },
  {
   "depthMm": 400.0,
   "from": "F3",
   "id": "GB3",
   "lengthMm": 3000.0,
   "to": "F4",
   "widthMm": 300.0,
   "xMm": 8000.0,
   "yMm": 6689.0
  }
 ],
 "projectId": "7c9e6f10-2a3b-4c5d-9e8f-1a2b3c4d5e6f"
}
""")


def _box(x_mm, y_mm, z_mm, size_x, size_y, size_z):
    return Part.makeBox(
        size_x,
        size_y,
        size_z,
        App.Vector(x_mm - size_x / 2.0, y_mm - size_y / 2.0, z_mm - size_z),
    )


def build():
    document = App.ActiveDocument
    if document is None:
        raise RuntimeError("no active document: the launcher always creates one")
    for footing in DESIGN["footings"]:
        shape = _box(
            footing["xMm"],
            footing["yMm"],
            0.0,
            footing["sizeXMm"],
            footing["sizeYMm"],
            footing["depthMm"],
        )
        obj = document.addObject("Part::Feature", f"Footing_{footing['id']}")
        obj.Shape = shape
        obj.Label = f"Footing {footing['id']}"
    for beam in DESIGN["gradeBeams"]:
        shape = _box(
            beam["xMm"],
            beam["yMm"],
            0.0,
            beam["lengthMm"],
            beam["widthMm"],
            beam["depthMm"],
        )
        obj = document.addObject("Part::Feature", f"GradeBeam_{beam['id']}")
        obj.Shape = shape
        obj.Label = f"Grade beam {beam['id']}"
    document.recompute()

    out_dir = os.environ.get("ARCHRES_JOB_OUTDIR")
    if out_dir:
        summary = {
            "projectId": DESIGN["projectId"],
            "footings": len(DESIGN["footings"]),
            "gradeBeams": len(DESIGN["gradeBeams"]),
            "excavation": DESIGN["excavation"],
        }
        target = pathlib.Path(out_dir) / "foundation-design.json"
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(
            json.dumps(summary, ensure_ascii=False, indent=1, sort_keys=True) + "\n",
            encoding="utf-8",
        )


build()

# --- the mesh export (W2.8): the workspace draws what the engine measured ---
import json as _json
import os as _os
import pathlib as _pathlib

_KINDS = {'Footing': 'footing', 'GradeBeam': 'grade-beam', 'Column': 'column', 'Beam': 'beam', 'Slab': 'slab'}
_PHASES = {'Footing': 'foundation', 'GradeBeam': 'foundation', 'Column': 'floor', 'Beam': 'floor', 'Slab': 'floor'}
_DEVIATION = 0.5


def _export_mesh(document, out_dir):
    objects = []
    for obj in document.Objects:
        shape = getattr(obj, "Shape", None)
        if shape is None or shape.isNull():
            continue
        points, facets = shape.tessellate(_DEVIATION)
        positions = []
        normals = []
        for facet in facets:
            if len(facet) != 3:
                continue
            p0, p1, p2 = points[facet[0]], points[facet[1]], points[facet[2]]
            ux, uy, uz = p1.x - p0.x, p1.y - p0.y, p1.z - p0.z
            vx, vy, vz = p2.x - p0.x, p2.y - p0.y, p2.z - p0.z
            nx = uy * vz - uz * vy
            ny = uz * vx - ux * vz
            nz = ux * vy - uy * vx
            length = (nx * nx + ny * ny + nz * nz) ** 0.5
            if length <= 0.0:
                continue
            nx, ny, nz = nx / length, ny / length, nz / length
            for index in facet:
                point = points[index]
                positions.extend([point.x, point.y, point.z])
                normals.extend([nx, ny, nz])
        box = shape.BoundBox
        prefix = obj.Name.split("_")[0]
        objects.append(
            {
                "id": obj.Name,
                "label": obj.Label,
                "kind": _KINDS.get(prefix, "other"),
                "phase": _PHASES.get(prefix, "other"),
                "volumeMm3": round(shape.Volume, 3),
                "bboxMinMm": [round(box.XMin, 4), round(box.YMin, 4), round(box.ZMin, 4)],
                "bboxMaxMm": [round(box.XMax, 4), round(box.YMax, 4), round(box.ZMax, 4)],
                "positions": [round(value, 4) for value in positions],
                "normals": [round(value, 6) for value in normals],
                "indices": list(range(len(positions) // 3)),
            }
        )
    payload = {"schemaVersion": '0.1.0', "units": "mm", "objects": objects}
    target = _pathlib.Path(out_dir) / 'mesh.json'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(
        _json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n", encoding="utf-8"
    )


_export_mesh(App.ActiveDocument, _os.environ["ARCHRES_JOB_OUTDIR"])

"""Typical floor macro - GENERATED by archres_core.design.floor (W2.3).

Do not edit: regenerate it from the Building Spec instead. The macro only *builds*; the
harness measures what it built (volume, bounding box, solids, validity).
"""

import json
import os
import pathlib

import FreeCAD as App
import Part

DESIGN = json.loads(r"""
{
 "baseZMm": 3200.0,
 "beams": [
  {
   "depthMm": 450.0,
   "id": "B1",
   "lengthMm": 3000.0,
   "widthMm": 300.0,
   "xMm": 2000.0,
   "yMm": 6689.0
  },
  {
   "depthMm": 450.0,
   "id": "B2",
   "lengthMm": 3000.0,
   "widthMm": 300.0,
   "xMm": 5000.0,
   "yMm": 6689.0
  },
  {
   "depthMm": 450.0,
   "id": "B3",
   "lengthMm": 3000.0,
   "widthMm": 300.0,
   "xMm": 8000.0,
   "yMm": 6689.0
  }
 ],
 "columns": [
  {
   "footingId": "F1",
   "heightMm": 3000.0,
   "id": "C1",
   "sizeMm": 300.0,
   "xMm": 500.0,
   "yMm": 6689.0
  },
  {
   "footingId": "F2",
   "heightMm": 3000.0,
   "id": "C2",
   "sizeMm": 300.0,
   "xMm": 3500.0,
   "yMm": 6689.0
  },
  {
   "footingId": "F3",
   "heightMm": 3000.0,
   "id": "C3",
   "sizeMm": 300.0,
   "xMm": 6500.0,
   "yMm": 6689.0
  },
  {
   "footingId": "F4",
   "heightMm": 3000.0,
   "id": "C4",
   "sizeMm": 300.0,
   "xMm": 9500.0,
   "yMm": 6689.0
  }
 ],
 "projectId": "7c9e6f10-2a3b-4c5d-9e8f-1a2b3c4d5e6f",
 "slab": {
  "originXMm": 350.0,
  "originYMm": 6539.0,
  "sizeXMm": 9300.0,
  "sizeYMm": 300.0,
  "thicknessMm": 125.0
 },
 "storeyIndex": 1
}
""")


def _box(x_mm, y_mm, z_bottom_mm, size_x, size_y, size_z):
    """A box whose *bottom* sits at z_bottom_mm (the storey's own level)."""
    return Part.makeBox(
        size_x,
        size_y,
        size_z,
        App.Vector(x_mm - size_x / 2.0, y_mm - size_y / 2.0, z_bottom_mm),
    )


def build():
    document = App.ActiveDocument
    if document is None:
        raise RuntimeError("no active document: the launcher always creates one")
    base_z = DESIGN["baseZMm"]
    for column in DESIGN["columns"]:
        shape = _box(
            column["xMm"],
            column["yMm"],
            base_z,
            column["sizeMm"],
            column["sizeMm"],
            column["heightMm"],
        )
        obj = document.addObject("Part::Feature", f"Column_{column['id']}")
        obj.Shape = shape
        obj.Label = f"Column {column['id']}"
    for beam in DESIGN["beams"]:
        shape = _box(
            beam["xMm"],
            beam["yMm"],
            base_z,
            beam["lengthMm"],
            beam["widthMm"],
            beam["depthMm"],
        )
        obj = document.addObject("Part::Feature", f"Beam_{beam['id']}")
        obj.Shape = shape
        obj.Label = f"Beam {beam['id']}"
    slab = DESIGN["slab"]
    shape = Part.makeBox(
        slab["sizeXMm"],
        slab["sizeYMm"],
        slab["thicknessMm"],
        App.Vector(slab["originXMm"], slab["originYMm"], base_z),
    )
    obj = document.addObject("Part::Feature", "Slab_1")
    obj.Shape = shape
    obj.Label = "Slab 1"
    document.recompute()

    out_dir = os.environ.get("ARCHRES_JOB_OUTDIR")
    if out_dir:
        summary = {
            "projectId": DESIGN["projectId"],
            "storeyIndex": DESIGN["storeyIndex"],
            "columns": len(DESIGN["columns"]),
            "beams": len(DESIGN["beams"]),
        }
        target = pathlib.Path(out_dir) / "floor-design.json"
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(
            json.dumps(summary, ensure_ascii=False, indent=1, sort_keys=True) + "\n",
            encoding="utf-8",
        )


build()

